from __future__ import annotations

from pathlib import Path

from menai_benchmark import BenchmarkCase, BenchmarkSuite, MenaiProgram

_SUITE_DIR = Path(__file__).resolve().parent
_FIXTURES_DIR = _SUITE_DIR / "fixtures"

# Fixtures are generated by generate_fixtures.py and committed so every run
# reads byte-identical inputs.
_FIXTURE_NAMES = [
    "text-4k.bin",
    "text-32k.bin",
    "incremental-16k.bin",
    "runs-32k.bin",
]

_ITERATIONS = 5

_EXPR = '(let ((deflate (import "deflate-compress"))) ((:: deflate compress) (dict-get inputs "input-data")))'


class Suite(BenchmarkSuite):
    """Benchmark suite for the Menai raw DEFLATE compressor."""

    name = "deflate-compress"
    description = "Compress raw byte inputs of varying content using the default block encoding."

    def cases(self) -> list[BenchmarkCase]:
        """Return one case per fixture file."""
        return [
            BenchmarkCase(
                name=name.removesuffix(".bin"),
                input=_FIXTURES_DIR / name,
                iterations=_ITERATIONS,
            )
            for name in _FIXTURE_NAMES
        ]

    def menai_program(self) -> MenaiProgram:
        """Return the compress expression, reading fixture bytes as its input."""
        return MenaiProgram(
            expression=_EXPR,
            fixture=lambda fixture_path: fixture_path.read_bytes(),
        )
